-- Quem já conversou com a unidade entra na base, com o nome do perfil do WhatsApp.
INSERT INTO "contatos_unidade" ("unidade_id", "telefone", "nome", "origem", "created_at")
SELECT n."unidade_id", r."telefone", max(c."nome_perfil"), 'conversa', min(r."recebida_em")
FROM "respostas_clientes" r
JOIN "numeros_whatsapp" n ON n."id" = r."numero_id"
LEFT JOIN "contatos" c ON c."telefone" = r."telefone"
GROUP BY n."unidade_id", r."telefone"
ON CONFLICT DO NOTHING;
